import React from 'react';
import { Link } from 'react-router-dom';
import { useAppNavigate } from '../hooks/useAppNavigate';
import { isStandalone } from './isStandalone';

interface DevRouteLinkProps {
  to: string;
  className?: string;
  children: React.ReactNode;
}

/** Dev grid link — bridge in shell dev; Link in standalone. */
export const DevRouteLink: React.FC<DevRouteLinkProps> = ({ to, className, children }) => {
  const appNavigate = useAppNavigate();

  if (isStandalone) {
    return (
      <Link to={to} className={className}>
        {children}
      </Link>
    );
  }

  return (
    <button type="button" className={className} onClick={() => appNavigate(to)}>
      {children}
    </button>
  );
};
